#include "stdlib/random/base/tinymt32.h"
#include "stdlib/random/base/shared.h"
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

// Forward declarations:
static inline int8_t next( struct BasePRNGObject *obj, uint64_t *out );
static inline int8_t normalized( struct BasePRNGObject *obj, double *out );
static inline void tinymt32_free( struct BasePRNGObject *obj );

static inline void create_state( stdlib_base_random_tinymt32_state_t * random, const uint32_t seed );
static inline void init_state( stdlib_base_random_tinymt32_state_t * random, const uint32_t *seed, const int64_t len );
static inline void next_state( stdlib_base_random_tinymt32_state_t *random );
static inline uint32_t tinymt32_temper(stdlib_base_random_tinymt32_state_t * random);
static uint32_t ini_func1(uint32_t x);
static uint32_t ini_func2(uint32_t x);

// Define constants for TinyMT32:
static const uint32_t TINYMT32_MASK = 0x7fffffff;
static const uint32_t TINYMT32_SH0 = 1;
static const uint32_t TINYMT32_SH1 = 10;
static const uint32_t TINYMT32_SH8 = 8;
static const uint32_t MIN_LOOP = 8;
static const uint32_t PRE_LOOP = 8;

// Define the maximum unsigned 32-bit integer:
static const uint32_t MAX_UINT32 = 4294967295;

// Define the maximum "safe" double-precision floating-point integer:
static const double FLOAT64_MAX_SAFE_INTEGER = 9007199254740991.0;

// Define a normalization constant when generating double-precision floating-point numbers:
static const double FLOAT64_NORMALIZATION_CONSTANT = 1.0 / ( FLOAT64_MAX_SAFE_INTEGER+1.0 );

// Define a multiplier (see Knuth TAOCP Vol2. 3rd Ed. P.106): 1812433253 => 01101100000001111000100101100101
static const uint32_t KNUTH_MULTIPLIER = 1812433253;

// 2^26: 67108864
static const double TWO_26 = 67108864.0;

// Define the maximum normalized pseudorandom double-precision floating-point number: ( (((2^32-1)>>>5)*2^26)+( (2^32-1)>>>6) ) / 2^53
static const double MAX_NORMALIZED = FLOAT64_MAX_SAFE_INTEGER * FLOAT64_NORMALIZATION_CONSTANT;

/**
* TinyMT32 PRNG.
*/
static struct BasePRNG tinymt32_prng = {
	"tinymt32",                                            // name
	(uint64_t)0,                                          // min
	(uint64_t)MAX_UINT32,                                 // max: (2^{32}-1)
	0.0,                                                  // min (normalized)
	MAX_NORMALIZED,                                       // max (normalized): (2^{53}-1)/2^{53}
	sizeof( stdlib_base_random_tinymt32_state_t ),         // state_size
	&next,                                                // next()
	&normalized,                                          // normalized()
	&tinymt32_free                                         // free()
};

/**
* Returns a pseudorandom integer.
*
* ## Notes
*
* -   The function returns `-1` if unable to generate a pseudorandom integer and `0` otherwise.
*
* ## References
*
* -   Matsumoto, Makoto, and Takuji Nishimura. 1998. "Mersenne Twister: A 623-dimensionally Equidistributed Uniform Pseudo-random Number Generator." _ACM Transactions on Modeling and Computer Simulation_ 8 (1). New York, NY, USA: ACM: 3–30. doi:[10.1145/272991.272995][@matsumoto:1998a].
*
* @param obj  PRNG object
* @param out  output address
* @return     status code
*/
static inline int8_t next( struct BasePRNGObject *obj, uint64_t *out ) {
	stdlib_base_random_tinymt32_state_t *so;
	uint32_t y;

	if ( obj == NULL || obj->prng != &tinymt32_prng ) {
		return -1;
	}

	// Retrieve the state object:
	so = (stdlib_base_random_tinymt32_state_t *)( obj->state );

	// Update the state:
	next_state( so );

	// Temper the state:
	y = tinymt32_temper(so);

	// Set the output value:
	*out = (uint64_t)( y );

	return 0;
}

/**
* Returns a pseudorandom double-precision floating-point number on the interval `[0, 1)`.
*
* ## Method
*
* -   When generating normalized double-precision floating-point numbers, we first generate two pseudorandom integers \\( x \\) and \\( y \\) on the interval \\( [0, 2^{32}-1] \\) for a combined \\( 64 \\) random bits.
*
* -   We would like \\( 53 \\) random bits to generate a 53-bit precision integer and, thus, want to discard \\( 11 \\) of the generated bits.
*
* -   We do so by discarding \\( 5 \\) bits from \\( x \\) and \\( 6 \\) bits from \\( y \\).
*
* -   Accordingly, \\( x \\) contains \\( 27 \\) random bits, which are subsequently shifted left \\( 26 \\) bits (multiplied by \\( 2^{26} \\), and \\( y \\) contains \\( 26 \\) random bits to fill in the lower \\( 26 \\) bits. When summed, they combine to comprise \\( 53 \\) random bits of a double-precision floating-point integer.
*
* -   As an example, suppose, for the sake of argument, the 32-bit PRNG generates the maximum unsigned 32-bit integer \\( 2^{32}-1 \\) twice in a row. Then,
*
*     ```c
*     uint32_t x = 4294967295 >> 5; // 00000111111111111111111111111111
*     uint32_t y = 4294967295 >> 6; // 00000011111111111111111111111111
*     ```
*
*     Multiplying \\( x \\) by \\( 2^{26} \\) returns \\( 9007199187632128 \\), which, in binary, is
*
*     ```binarystring
*     0 10000110011 11111111111111111111 11111100000000000000000000000000
*     ```
*
*     Adding \\( y \\) yields \\( 9007199254740991 \\) (the maximum "safe" double-precision floating-point integer value), which, in binary, is
*
*     ```binarystring
*     0 10000110011 11111111111111111111 11111111111111111111111111111111
*     ```
*
* -   Similarly, suppose the 32-bit PRNG generates the following values
*
*     ```c
*     uint32_t x = 1 >> 5;  // 0 => 00000000000000000000000000000000
*     uint32_t y = 64 >> 6; // 1 => 00000000000000000000000000000001
*     ```
*
*     Multiplying \\( x \\) by \\( 2^{26} \\) returns \\( 0 \\), which, in binary, is
*
*     ```binarystring
*     0 00000000000 00000000000000000000 00000000000000000000000000000000
*     ```
*
*     Adding \\( y \\) yields \\( 1 \\), which, in binary, is
*
*     ```binarystring
*     0 01111111111 00000000000000000000 00000000000000000000000000000000
*     ```
*
* -   As different combinations of \\( x \\) and \\( y \\) are generated, different combinations of double-precision floating-point exponent and significand bits will be toggled, thus generating pseudorandom double-precision floating-point numbers.
*
* ## Notes
*
* -   The function returns `-1` if unable to generate a pseudorandom number and `0` otherwise.
*
* ## References
*
* -   Harase, Shin. 2017. "Conversion of Mersenne Twister to double-precision floating-point numbers." _ArXiv_ abs/1708.06018 (September). <https://arxiv.org/abs/1708.06018>.
*
* @param obj  PRNG object
* @param out  output address
* @return     status code
*/
static inline int8_t normalized( struct BasePRNGObject *obj, double *out ) {
	uint64_t x;
	uint64_t y;
	if ( obj == NULL || obj->prng != &tinymt32_prng ) {
		return -1;
	}
	next( obj, &x);
	x >>= 5;

	next( obj, &y );
	y >>= 6;

	// Note: casting `x` and `y` to doubles here is fine, as neither will ever exceed the maximum "safe" double-precision floating-point number:
	*out = ( ((double)x*TWO_26)+(double)y ) * FLOAT64_NORMALIZATION_CONSTANT;

	return 0;
}

/**
* Frees a PRNG's allocated memory.
*
* @param obj  PRNG object
*/
static inline void tinymt32_free( struct BasePRNGObject *obj ) {
	if ( obj == NULL || obj->prng != &tinymt32_prng ) {
		return;
	}
	stdlib_base_random_tinymt32_state_t *state = (stdlib_base_random_tinymt32_state_t *)( obj->state );
	free( state->seed );
	free( obj->state );
	free( obj );
}

/**
* Updates the PRNG state.
*
* @param random tinymt internal state
*/
static inline void next_state( stdlib_base_random_tinymt32_state_t *random ) {
	uint32_t x;
	uint32_t y;

	y = random->state[3];
	x = (random->state[0] & TINYMT32_MASK)
		^ random->state[1]
		^ random->state[2];
	x ^= (x << TINYMT32_SH0);
	y ^= (y >> TINYMT32_SH0) ^ x;
	random->state[0] = random->state[1];
	random->state[1] = random->state[2];
	random->state[2] = x ^ (y << TINYMT32_SH1);
	random->state[3] = y;
	int32_t const a = -((int32_t)(y & 1)) & (int32_t)random->mat1;
	int32_t const b = -((int32_t)(y & 1)) & (int32_t)random->mat2;
	random->state[1] ^= (uint32_t)a;
	random->state[2] ^= (uint32_t)b;
}

/**
 * This function outputs 32-bit unsigned integer from internal state.
 * Users should not call this function directly.
 * @param random tinymt internal status
 * @return 32-bit unsigned pseudorandom number
 */
static inline uint32_t tinymt32_temper(stdlib_base_random_tinymt32_state_t * random) {
	uint32_t t0, t1;
	t0 = random->state[3];
	t1 = random->state[0]
		+ (random->state[2] >> TINYMT32_SH8);
	t0 ^= t1;
	if ((t1 & 1) != 0) {
		t0 ^= random->tmat;
	}
	return t0;
}

/**
 * This function represents a function used in the initialization
 * by init_by_array
 * @param x 32-bit integer
 * @return 32-bit integer
 */
static uint32_t ini_func1(uint32_t x) {
	return (x ^ (x >> 27)) * UINT32_C(1664525);
}

/**
 * This function represents a function used in the initialization
 * by init_by_array
 * @param x 32-bit integer
 * @return 32-bit integer
 */
static uint32_t ini_func2(uint32_t x) {
	return (x ^ (x >> 27)) * UINT32_C(1566083941);
}

/**
* Creates an initial PRNG state.
*
* @param random  tinymt internal status
* @param seed    seed
*/
static inline void create_state(stdlib_base_random_tinymt32_state_t * random, const uint32_t seed) {
	random->seed = malloc(sizeof(uint32_t));
	random->seed[0] = seed;
	random->seed_length = 1;
	random->state[0] = seed;
	random->state[1] = random->mat1;
	random->state[2] = random->mat2;
	random->state[3] = random->tmat;

	for (unsigned int i = 1; i < MIN_LOOP; i++) {
		random->state[i & 3] ^= i + KNUTH_MULTIPLIER
			* (random->state[(i - 1) & 3]
				^ (random->state[(i - 1) & 3] >> 30));
	}

	for (unsigned int i = 0; i < PRE_LOOP; i++) {
		next_state(random);
	}
}

/**
* Initializes a PRNG state array according to a seed array.
*
* @param random tinymt internal status
* @param seed   seed array
* @param len    seed array length
*/
static inline void init_state( stdlib_base_random_tinymt32_state_t * random, const uint32_t *seed, const int64_t len ) {
	const unsigned int lag = 1;
	const unsigned int mid = 1;
	const unsigned int size = 4;
	unsigned int i, j;
	unsigned int count;
	uint32_t r;
	uint32_t * st = &random->state[0];

	random->seed = malloc(sizeof(uint32_t));
	memcpy(random->seed, seed, sizeof(uint32_t)*len);
	random->seed_length = len;

	st[0] = 0;
	st[1] = random->mat1;
	st[2] = random->mat2;
	st[3] = random->tmat;
	if (len + 1 > MIN_LOOP) {
		count = (unsigned int)len + 1;
	} else {
		count = MIN_LOOP;
	}
	r = ini_func1(st[0] ^ st[mid % size]
					^ st[(size - 1) % size]);
	st[mid % size] += r;
	r += (unsigned int)len;
	st[(mid + lag) % size] += r;
	st[0] = r;
	count--;
	for (i = 1, j = 0; (j < count) && (j < (unsigned int)len); j++) {
		r = ini_func1(st[i % size]
						^ st[(i + mid) % size]
						^ st[(i + size - 1) % size]);
		st[(i + mid) % size] += r;
		r += seed[j] + i;
		st[(i + mid + lag) % size] += r;
		st[i % size] = r;
		i = (i + 1) % size;
	}
	for (; j < count; j++) {
		r = ini_func1(st[i % size]
						^ st[(i + mid) % size]
						^ st[(i + size - 1) % size]);
		st[(i + mid) % size] += r;
		r += i;
		st[(i + mid + lag) % size] += r;
		st[i % size] = r;
		i = (i + 1) % size;
	}
	for (j = 0; j < size; j++) {
		r = ini_func2(st[i % size]
						+ st[(i + mid) % size]
						+ st[(i + size - 1) % size]);
		st[(i + mid) % size] ^= r;
		r -= i;
		st[(i + mid + lag) % size] ^= r;
		st[i % size] = r;
		i = (i + 1) % size;
	}
	for (i = 0; i < PRE_LOOP; i++) {
		next_state(random);
	}
}


/**
* Returns a pointer to a dynamically allocated PRNG.
*
* ## Notes
*
* -   The user is responsible for freeing the allocated memory.
*
* @param seed  pointer to a seed array
* @param len   seed array length
* @return      pointer to a dynamically allocated PRNG or, if unable to allocate memory, a null pointer
*
* @example
* #include "stdlib/random/base/tinymt32.h"
* #include "stdlib/random/base/shared.h"
* #include <stdlib.h>
* #include <stdio.h>
* #include <stdint.h>
*
* // Define a PRNG seed:
* uint32_t seed[] = { 12345 };
*
* // Create a PRNG:
* struct BasePRNGObject *obj = stdlib_base_random_tinymt32_allocate( seed, 1 );
* if ( obj == NULL ) {
*     fprintf( stderr, "Error allocating memory.\n" );
*     exit( 1 );
* }
*
* uint64_t r;
* int8_t status = obj->prng->next( obj, &r );
* if ( status != 0 ) {
*     fprintf( stderr, "Unexpected result.\n" );
*     exit( 1 );
* }
*
* // ...
*
* status = obj->prng->next( obj, &r );
*
* // ...
*
* status = obj->prng->next( obj, &r );
*
* // ...
*
* // Free allocated memory:
* stdlib_base_random_tinymt32_free( obj );
*/
struct BasePRNGObject * stdlib_base_random_tinymt32_allocate( const uint32_t *seed, const int64_t len ) {
	stdlib_base_random_tinymt32_state_t *state;
	struct BasePRNGObject *obj;

	obj = malloc( sizeof( struct BasePRNGObject ) );
	if ( obj == NULL ) {
		return NULL;
	}
	state = malloc( sizeof( stdlib_base_random_tinymt32_state_t ) );
	if ( state == NULL ) {
		free( obj ); // prevent memory leaks
		return NULL;
	}
	obj->prng = &tinymt32_prng;
	obj->state = state;

	// Initialize mat1, mat2, and tmat before using them
	state->mat1 = 0x8f7011ee;  // Default parameter values from TinyMT
	state->mat2 = 0xfc78ff1f;  // Default parameter values from TinyMT
	state->tmat = 0x3793fdff;  // Default parameter values from TinyMT

	// Initialize the PRNG state:
	create_state( state, seed[0] );
	init_state( state, seed, len );

	return obj;
}

/**
* Frees a PRNG's allocated memory.
*
* @param obj  PRNG object
*
* @example
* #include "stdlib/random/base/tinymt32.h"
* #include "stdlib/random/base/shared.h"
* #include <stdlib.h>
* #include <stdio.h>
* #include <stdint.h>
*
* // Define a PRNG seed:
* uint32_t seed[] = { 12345 };
*
* // Create a PRNG:
* struct BasePRNGObject *obj = stdlib_base_random_tinymt32_allocate( seed, 1 );
* if ( obj == NULL ) {
*     fprintf( stderr, "Error allocating memory.\n" );
*     exit( 1 );
* }
*
* uint64_t r;
* int8_t status = obj->prng->next( obj, &r );
* if ( status != 0 ) {
*     fprintf( stderr, "Unexpected result.\n" );
*     exit( 1 );
* }
*
* // ...
*
* status = obj->prng->next( obj, &r );
*
* // ...
*
* status = obj->prng->next( obj, &r );
*
* // ...
*
* // Free allocated memory:
* stdlib_base_random_tinymt32_free( obj );
*/
void stdlib_base_random_tinymt32_free( struct BasePRNGObject *obj ) {
	if ( obj == NULL || obj->prng != &tinymt32_prng ) {
		return;
	}
	obj->prng->free( obj );
}

/**
* Returns the PRNG seed length.
*
* ## Notes
*
* -   The function returns `-1` if unable to resolve a PRNG seed length and `0` otherwise.
*
* @param obj   PRNG object
* @param len   output address
* @return      status code
*
* @example
* #include "stdlib/random/base/tinymt32.h"
* #include "stdlib/random/base/shared.h"
* #include <stdlib.h>
* #include <stdio.h>
* #include <stdint.h>
*
* // Define a PRNG seed:
* uint32_t seed1[] = { 12345 };
*
* // Create a PRNG:
* struct BasePRNGObject *obj = stdlib_base_random_tinymt32_allocate( seed1, 1 );
* if ( obj == NULL ) {
*     fprintf( stderr, "Error allocating memory.\n" );
*     exit( 1 );
* }
*
* // ...
*
* // Get the seed length:
* int64_t seed_length;
* int8_t status = stdlib_base_random_tinymt32_seed_length( obj, &seed_length );
* if ( status != 0 ) {
*     fprintf( stderr, "Error encountered when attempting to retrieve the PRNG seed length.\n" );
*     exit( 1 );
* }
*
* // Get the PRNG seed:
* uint32_t *seed2 = (uint32_t *)malloc( sizeof( uint32_t )*seed_length );
* if ( seed2 == NULL ) {
*     fprintf( stderr, "Error allocating memory.\n" );
*     exit( 1 );
* }
* status = stdlib_base_random_tinymt32_seed( obj, seed2 );
* if ( status != 0 ) {
*     fprintf( stderr, "Error encountered when attempting to retrieve the PRNG seed.\n" );
*     exit( 1 );
* }
*
* // Use the seed to, e.g., create another PRNG which will generate the same sequence...
*
* // Free allocated memory:
* stdlib_base_random_tinymt32_free( obj );
* free( seed2 );
*/
int8_t stdlib_base_random_tinymt32_seed_length( const struct BasePRNGObject *obj, int64_t *len ) {
	if ( obj == NULL || obj->prng != &tinymt32_prng ) {
		return -1;
	}
	// Retrieve the state object:
	const stdlib_base_random_tinymt32_state_t *state = (stdlib_base_random_tinymt32_state_t *)( obj->state );

	// Set the seed length:
	*len = (int64_t)( state->seed_length );

	return 0;
}

/**
* Returns a PRNG seed.
*
* ## Notes
*
* -   The function returns `-1` if unable to resolve a PRNG seed and `0` otherwise.
*
* @param obj   PRNG object
* @param seed  output address
* @return      status code
*
* @example
* #include "stdlib/random/base/tinymt32.h"
* #include "stdlib/random/base/shared.h"
* #include <stdlib.h>
* #include <stdio.h>
* #include <stdint.h>
*
* // Define a PRNG seed:
* uint32_t seed1[] = { 12345 };
*
* // Create a PRNG:
* struct BasePRNGObject *obj = stdlib_base_random_tinymt32_allocate( seed1, 1 );
* if ( obj == NULL ) {
*     fprintf( stderr, "Error allocating memory.\n" );
*     exit( 1 );
* }
*
* // ...
*
* // Get the seed length:
* int64_t seed_length;
* int8_t status = stdlib_base_random_tinymt32_seed_length( obj, &seed_length );
* if ( status != 0 ) {
*     fprintf( stderr, "Error encountered when attempting to retrieve the PRNG seed length.\n" );
*     exit( 1 );
* }
*
* // Get the PRNG seed:
* uint32_t *seed2 = (uint32_t *)malloc( sizeof( uint32_t )*seed_length );
* if ( seed2 == NULL ) {
*     fprintf( stderr, "Error allocating memory.\n" );
*     exit( 1 );
* }
* status = stdlib_base_random_tinymt32_seed( obj, seed2 );
* if ( status != 0 ) {
*     fprintf( stderr, "Error encountered when attempting to retrieve the PRNG seed.\n" );
*     exit( 1 );
* }
*
* // Use the seed to, e.g., create another PRNG which will generate the same sequence...
*
* // Free allocated memory:
* stdlib_base_random_tinymt32_free( obj );
* free( seed2 );
*/
int8_t stdlib_base_random_tinymt32_seed( const struct BasePRNGObject *obj, uint32_t *seed ) {
	if ( obj == NULL || obj->prng != &tinymt32_prng ) {
		return -1;
	}
	// Retrieve the state object:
	const stdlib_base_random_tinymt32_state_t *state = (stdlib_base_random_tinymt32_state_t *)( obj->state );

	// Copy the seed array:
	memcpy( seed, state->seed, sizeof( uint32_t )*(state->seed_length) );

	return 0;
}

/**
* Returns a **copy** of the current PRNG state.
*
* ## Notes
*
* -   The user is responsible for freeing the allocated memory.
*
* @param obj  PRNG object
* @return     pointer to a copy of the PRNG's internal state or, if unable to allocate memory, a null pointer
*
* @example
* #include "stdlib/random/base/tinymt32.h"
* #include "stdlib/random/base/shared.h"
* #include <stdlib.h>
* #include <stdio.h>
* #include <stdint.h>
*
* // Define a PRNG seed:
* uint32_t seed[] = { 12345 };
*
* // Create a PRNG:
* struct BasePRNGObject *obj = stdlib_base_random_tinymt32_allocate( seed, 1 );
* if ( obj == NULL ) {
*     fprintf( stderr, "Error allocating memory.\n" );
*     exit( 1 );
* }
*
* stdlib_base_random_tinymt32_state_t *state = (stdlib_base_random_tinymt32_state_t *)stdlib_base_random_tinymt32_state( obj );
* if ( state == NULL ) {
*     fprintf( stderr, "Unable to retrieve PRNG state.\n" );
*     exit( 1 );
* }
*
* // Use the captured state to, e.g., sync another PRNG or to reset a PRNG to a particular state in order to "replay" generated values at a later point in time...
*
* // Free allocated memory:
* stdlib_base_random_tinymt32_free( obj );
*
* free( state->seed );
* free( state );
*/
void * stdlib_base_random_tinymt32_state( const struct BasePRNGObject *obj ) {
	const stdlib_base_random_tinymt32_state_t *so;
	stdlib_base_random_tinymt32_state_t *state;
	uint64_t nbytes;
	uint32_t *seed;
	if ( obj == NULL || obj->prng != &tinymt32_prng ) {
		return NULL;
	}
	state = (stdlib_base_random_tinymt32_state_t *)malloc( obj->prng->state_size );
	if ( state == NULL ) {
		return NULL;
	}
	// Copy the state
	memcpy( state, obj->state, obj->prng->state_size );
	so = (stdlib_base_random_tinymt32_state_t *)( obj->state );

	// Now we can safely use seed_length
	nbytes = sizeof( uint32_t ) * (state->seed_length);
	seed = (uint32_t *)malloc( nbytes );
	if ( seed == NULL ) {
		free( state ); // prevent memory leaks
		return NULL;
	}

	// Explicitly copy the seed array to prevent external mutation:
	memcpy( seed, so->seed, nbytes );
	state->seed = seed;

	return (void *)state;
}

/**
* Sets the PRNG state.
*
* ## Notes
*
* -   The function returns `-1` if unable to set a PRNG state and `0` otherwise.
*
* @param obj    PRNG object
* @param state  state
* @return       status code
*
* @example
* #include "stdlib/random/base/tinymt32.h"
* #include "stdlib/random/base/shared.h"
* #include <stdlib.h>
* #include <stdio.h>
* #include <stdint.h>
*
* // Define a PRNG seed:
* uint32_t seed[] = { 12345 };
*
* // Create a PRNG:
* struct BasePRNGObject *obj = stdlib_base_random_tinymt32_allocate( seed, 1 );
* if ( obj == NULL ) {
*     fprintf( stderr, "Error allocating memory.\n" );
*     exit( 1 );
* }
*
* uint64_t r;
* int8_t status = obj->prng->next( obj, &r );
* if ( status != 0 ) {
*     fprintf( stderr, "Unexpected result.\n" );
*     exit( 1 );
* }
*
* // ...
*
* status = obj->prng->next( obj, &r );
*
* // ...
*
* status = obj->prng->next( obj, &r );
*
* // ...
*
* // Retrieve the current PRNG state...
* stdlib_base_random_tinymt32_state_t *state = (stdlib_base_random_tinymt32_state_t *)stdlib_base_random_tinymt32_state( obj );
* if ( state == NULL ) {
*     fprintf( stderr, "Error encountered when attempting to retrieve PRNG state.\n" );
*     exit( 1 );
* }
*
* // ...
*
* status = obj->prng->next( obj, &r );
*
* // ...
*
* status = obj->prng->next( obj, &r );
*
* // ...
*
* // Reset the PRNG to a previous state...
* status = stdlib_base_random_tinymt32_set( obj, (void *)state );
* if ( status != 0 ) {
*     fprintf( stderr, "Error encountered when attempting to set PRNG state.\n" );
*     exit( 1 );
* }
*
* // ...
*
* status = obj->prng->next( obj, &r );
*
* // ...
*
* status = obj->prng->next( obj, &r );
*
* // ...
*
* // Free allocated memory:
* stdlib_base_random_tinymt32_free( obj );
*
* free( state->seed );
* free( state );
*/
int8_t stdlib_base_random_tinymt32_set( struct BasePRNGObject *obj, const void *state ) {
	stdlib_base_random_tinymt32_state_t *vstate;
	uint64_t nbytes;
	uint32_t *seed;
	if ( obj == NULL || state == NULL || obj->prng != &tinymt32_prng ) {
		return -1;
	}
	// Copy the provided seed array:
	vstate = ( stdlib_base_random_tinymt32_state_t *)state;
	nbytes = sizeof( uint32_t ) * ( vstate->seed_length );
	seed = (uint32_t *)malloc( nbytes );
	if ( seed == NULL ) {
		return -1;
	}
	memcpy( seed, vstate->seed, nbytes );

	// Retrieve the current PRNG state:
	vstate = ( stdlib_base_random_tinymt32_state_t *)( obj->state );

	// Free the memory held by the current seed array:
	free( vstate->seed );

	// Overwrite the current state with the provided state:
	memcpy( vstate, state, obj->prng->state_size );

	// Update the seed array pointer:
	vstate->seed = seed;

	return 0;
}
